import "core-js/modules/es.array.push.js";
import axios from 'axios';
export default {
  data() {
    return {
      settingsForm: {
        default_currency: '',
        use_default_currency_where_relevant: false,
        chart_frequency: '',
        chart_timeline: '',
        NAV_barchart_default_breakdown: '',
        digits: 0,
        custom_brokers: []
      },
      currencyChoices: [],
      frequencyChoices: [],
      timelineChoices: [],
      navBreakdownChoices: [],
      brokerChoices: []
    };
  },
  mounted() {
    this.fetchSettings();
    this.fetchChoices();
  },
  methods: {
    async fetchSettings() {
      try {
        const response = await axios.get('/api/user/settings/');
        this.settingsForm = response.data;
      } catch (error) {
        console.error('Error fetching settings:', error);
      }
    },
    async fetchChoices() {
      try {
        const response = await axios.get('/api/user/settings/choices/');
        this.currencyChoices = response.data.currency_choices;
        this.frequencyChoices = response.data.frequency_choices;
        this.timelineChoices = response.data.timeline_choices;
        this.navBreakdownChoices = response.data.nav_breakdown_choices;
        this.brokerChoices = response.data.broker_choices;
      } catch (error) {
        console.error('Error fetching choices:', error);
      }
    },
    async saveSettings() {
      try {
        await axios.post('/api/user/settings/', this.settingsForm);
        this.$router.push('/profile');
      } catch (error) {
        console.error('Error saving settings:', error);
      }
    }
  }
};
